    public function getFileTypeAttribute()
    {
        $label = 'Fail Terbuka';

        if ($this->is_nt) {
            $label = 'Fail Sulit';
        } elseif ($this->is_volume) {
            $label = 'Fail Jilid';
        }

        return '<div class="rounded small fw-medium shadow-sm p-1" style="text-align: center; color: white; background-color: rgb(105, 105, 105);">' . $label . '</div>';

    }

    public static function getInactivePosition($positionId)
    {
        $appPosition = RefPositions::find($positionId);
        if($appPosition && $appPosition->status == 0){
            return [
                'id' => $appPosition->id,
                'desc' => $appPosition->description.($appPosition->gred ? ' - '.$appPosition->gred : ''),
            ];
        } else { return null; }
    }

    /**
     * Define the scope
     */
    public function scopeAppInfo($query)
    {
        return $query->with([
            'file',
            'branch',
            'integration',
            'file.documents',
            'file.fileHistory',
        ]);
    }


    public function files()
    {
        return $this->hasMany(FileInfo::class, 'app_id', 'id');
    }

    public function file()
    {
        return $this->hasOne(FileInfo::class, 'app_id', 'id')->latest();
    }

